            if (relapse) shiftsLeft = Math.min(100, shiftsLeft + 0.4 * (100 - shiftsLeft));
            /* hires beyond 10 points a phase meet a thin nursing labour market (case: 23 vacancies, pay below sector) */
            var hires = Math.min(s, 10) + 0.4 * Math.max(0, s - 10);
            var staff = ds.staffAdded + hires;
            if (relapse) staff = staff * 0.8;
            var cap = ds.capability * 0.7 + Math.sqrt(t);
            var streak = f === 'structural' ? (ds.structStreak || 0) + 1 : 0;
            var rstreak = f === 'reactive' ? (ds.reactStreak || 0) + 1 : 0;
            /* focus: preventive spends support better; structural redesign pays from its second phase in a row;
               reactive treats cases now, and the relief fades (TN 5.3, Q3) */
            var fmW = f === 'preventive' ? 1.2 : 1.0;
            var fmD = f === 'structural' ? (streak >= 2 ? 1.3 : 0.95) : (f === 'preventive' ? 1.1 : 0.85);
            /* removed 24h shifts need staff to cover them, on top of the vacancies (TN Q4) */
            var need = 4 + 0.15 * (100 - shiftsLeft);
            var gap = Math.max(0, need - staff);
            /* change load: very deep cuts or mass hiring in one phase disrupt handovers and teams */
            var shock = Math.min(3, Math.max(0, sh - 30) / 10 + Math.max(0, s - 10) / 5);
            var redesign = (C.SW * (1 - shiftsLeft / 100) + C.ST * Math.min(1, staff / 12)) * fmD;
            var Bstar = 42 + C.DR - redesign + C.GB * (gap - 4) - C.WC * Math.sqrt(w) * fmW - C.CC * cap
                      + C.TP * t * (shiftsLeft / 100) + C.SB * shock;
            Bstar = Math.max(8, Bstar);
            var kB = C.K, kR = C.K;
            if (f === 'reactive' && period >= 3) { kB = C.K * 0.6; kR = C.K * 0.5; }
            var Bu = Bu0 + kB * (Bstar - Bu0);
            var rel = f === 'reactive' ? Math.min(6, 0.4 * Math.sqrt(w)) * Math.pow(0.55, rstreak - 1) : 0;
            var newB = Math.max(5, Bu - rel);
            var Rstar = 38 + C.RDR + 0.45 * (newB - 42) - C.RS * (1 - shiftsLeft / 100) - C.RT * Math.min(1, staff / 12) + 0.3 * (gap - 4);
            var newR = Math.max(6, prevR + kR * (Rstar - prevR));
            var Pstar = 74 + 1.2 * cap + 0.3 * Math.min(staff, 20) + 0.2 * (42 - newB) - 1.5 * gap
                      - C.TD * t * t - 0.02 * s * s - C.SP * shock;
            var newP = Math.max(40, Math.min(100, ds.productivity + 0.5 * (Pstar - ds.productivity)));

            var cost = w * 1000000 + s * 25000000 + sh * 8000000 + t * 6000000;
            var B1 = Math.round(newB * 10) / 10, R1 = Math.round(newR * 10) / 10, P1 = Math.round(newP * 10) / 10;
            var netSavings = (prevB - B1) * 18000000 + (prevR - R1) * 22000000;

            ds.cash = ds.cash - cost + netSavings;
            ds.burnoutBase = Bu;
            ds.burnoutIndex = B1;
            ds.rotation = R1;
            ds.productivity = P1;
            ds.shiftsLeft = shiftsLeft;
            ds.staffAdded = staff;
            ds.capability = cap;
            ds.structStreak = streak;
            ds.reactStreak = rstreak;
            ds.engagement = Math.max(0, Math.min(100, 55 + (42 - B1) * 0.8));

            ds.burnoutHistory.push(ds.burnoutIndex);
            ds.rotationHistory.push(ds.rotation);
            ds.productivityHistory.push(ds.productivity);

            /* composite 0-100 persisted for the gradebook (domainState.performance.overallScore) */
            var _sc = this._score(ds.burnoutIndex, ds.rotation, ds.productivity);
            ds.score = _sc;
            ds.performance = { overallScore: _sc, grade: this._grade(_sc) };

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            return {
                period: period, cost: cost, savings: Math.round(netSavings), netCost: Math.round(cost - netSavings),
                burnoutIndex: B1, rotation: R1, productivity: P1, focus: f,
                shiftsLeft: Math.round(shiftsLeft * 10) / 10, staffAdded: Math.round(staff * 10) / 10,
                gap: Math.round(gap * 10) / 10, shock: Math.round(shock * 10) / 10, relapse: relapse, score: _sc
            };
        }

