            if (results.relapse) return t('hint_relapse');
            if (results.gap > 3) return t('hint_gap');
            if (results.shock >= 1) return t('hint_shock');
            if (results.burnoutIndex > 35 && state.currentPeriod >= 2) return t('hint_high_burnout');
            if (results.focus === 'reactive' && state.currentPeriod >= 3) return t('hint_reactive');
            if (results.productivity < 75) return t('hint_low_productivity');
            if (results.rotation < 15 && results.burnoutIndex < 20) return t('hint_excellent');
