        _score(burnout, rotation, productivity) {
            var bc = Math.max(0, Math.min(100, (45 - burnout) / 35 * 100));
            var rc = Math.max(0, Math.min(100, (40 - rotation) / 32 * 100));
            var pc = Math.max(0, Math.min(100, (productivity - 60) / 30 * 100));
            return Math.max(0, Math.min(100, Math.round(0.40 * bc + 0.35 * rc + 0.25 * pc)));
        }

        _grade(score) {
            if (score >= 80) return 'Excelente';
            if (score >= 60) return 'Bueno';
            if (score >= 40) return 'Aceptable';
            return 'Insuficiente';
        }

        /* Mistakes named in the debrief, detected from the run history (TN 7 Q1 to Q4, 9.2, 13). */
        _diagnose(history) {
            var n = history.length, avg = function (k) { return history.reduce(function (a, h) { return a + (Number((h.decisions || {})[k]) || 0); }, 0) / Math.max(1, n); };
            var foc = history.map(function (h) { return (h.decisions || {}).focus; });
            var res = history.map(function (h) { return h.results || {}; });
            var last = res[n - 1] || {};
            var aw = avg('wellnessBudget'), as = avg('staffingIncrease'), ash = avg('shiftReduction'), at = avg('trainingHours');
            var out = [];
            var noDemand = ash < 5 && as < 2;
            if (noDemand && at >= 10) out.push('mis_resilience');
            else if (noDemand && aw >= 200) out.push('mis_psych');
            var early = foc.slice(0, 2).every(function (x) { return x === 'structural' || x === 'preventive'; });
            if (n >= 3 && early && foc.slice(2).some(function (x) { return x === 'reactive'; })) out.push('mis_reactive_turn');
            else if (foc.filter(function (x) { return x === 'reactive'; }).length >= 2) out.push('mis_reactive');
            if ((last.shiftsLeft == null ? 100 : last.shiftsLeft) >= 85) out.push('mis_shifts_kept');
            if (res.some(function (r) { return r.relapse; })) out.push('mis_abandoned');
            if (res.some(function (r) { return r.gap > 4; })) out.push('mis_gap');
            if (res.some(function (r) { return r.shock >= 1; })) out.push('mis_shock');
            return out;
        }

        _turningPoint(history) {
            var prev = 21, best = null;
            for (var i = 0; i < history.length; i++) {
                var sc = (history[i].results || {}).score;
                if (typeof sc !== 'number') continue;
                var dlt = sc - prev;
                if (best === null || Math.abs(dlt) > Math.abs(best.d)) best = { p: i + 1, d: dlt, sc: sc };
                prev = sc;
            }
            return best;
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var last = history[history.length - 1];
            var burnout = last.results ? last.results.burnoutIndex : 42;
            var rotation = last.results ? last.results.rotation : 38;
            var productivity = last.results ? last.results.productivity : 78;
            var score = this._score(burnout, rotation, productivity);
            var performance = this._grade(score);
            var tierKey = { 'Excelente': 'tier_excelente', 'Bueno': 'tier_bueno', 'Aceptable': 'tier_aceptable', 'Insuficiente': 'tier_insuficiente' }[performance];

            var t = function (k) { return window.mySimulation.t(k); };
            var mistakes = this._diagnose(history);
            var insights = mistakes.map(function (k) { return t(k); });
            if (!mistakes.length) {
                if (burnout < 20 && rotation < 20) insights.push(t('sum_sustained'));
                else insights.push(t('sum_partial'));
            }
            if (burnout < 20 && rotation < 20 && productivity >= 78) insights.push(t('sum_target_met'));
            else insights.push(t('sum_target_missed'));
            if (productivity < 78) insights.push(t('sum_productivity_low'));
            insights = insights.slice(0, 5);

            return {
                burnoutFinal: burnout,
                rotationFinal: rotation,
                productivityFinal: productivity,
                overallScore: score,
                totalScore: score,
                score: score,
                totalPeriods: history.length,
                performance: performance,
                performanceLabel: tierKey ? t(tierKey) : performance,
                mistakes: mistakes,
                turningPoint: this._turningPoint(history),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var self = this;
            var t = function (k) { return window.mySimulation.t(k); };
            var score = (typeof summary.overallScore === 'number') ? summary.overallScore : 0;
            var perf = this._grade(score);
            var tierKey = { 'Excelente': 'tier_excelente', 'Bueno': 'tier_bueno', 'Aceptable': 'tier_aceptable', 'Insuficiente': 'tier_insuficiente' }[perf];
            var perfL = tierKey ? t(tierKey) : perf;
            var color = score >= 80 ? '#1d7a6f' : (score >= 60 ? '#8a6d00' : (score >= 40 ? '#b45309' : '#c1121f'));
            var kpis = [
                [t('burnout_label'), (typeof summary.burnoutFinal === 'number') ? (self._num(summary.burnoutFinal, 1) + '%') : '-'],
                [t('rotation_label'), (typeof summary.rotationFinal === 'number') ? (self._num(summary.rotationFinal, 1) + '%') : '-'],
                [t('productivity_label'), (typeof summary.productivityFinal === 'number') ? self._num(summary.productivityFinal, 1) : '-']
            ];
            var kpiRow = kpis.map(function(k) { return '<span style="display:inline-block;margin:4px 10px;"><strong>' + k[1] + '</strong> ' + k[0] + '</span>'; }).join('');
            var ins = summary.insights || [];
            var items = ins.map(function(x) { return '<li>' + x + '</li>'; }).join('');
            var insBlock = items ? ('<h5 style="margin-top:12px;">' + t('insights_heading') + '</h5><ul style="text-align:left;margin:4px auto 0;display:inline-block;">' + items + '</ul>') : '';
            var tp = summary.turningPoint;
            var tpBlock = '';
            if (tp && typeof tp.p === 'number') {
                tpBlock = '<p style="margin-top:10px;"><strong>' + t('turning_heading') + '</strong> ' +
                    t(tp.d >= 0 ? 'turning_up' : 'turning_down').replace('{p}', tp.p).replace('{d}', Math.abs(Math.round(tp.d))) + '</p>';
            }
            var qs = '<h5 style="margin-top:12px;">' + t('questions_heading') + '</h5><ol style="text-align:left;margin:4px auto 0;display:inline-block;"><li>' + t('question_1') + '</li><li>' + t('question_2') + '</li></ol>';
            return '<div class="completion-message text-center p-4" role="status" aria-live="polite">' +
                '<h4 style="margin-bottom:8px;">' + t('completion_heading') + '</h4>' +
                '<div style="font-size:2.6rem;font-weight:800;color:' + color + ';">' + score + '/100</div>' +
                '<p class="lead" style="margin:2px 0;">' + t('overall_score_label') + '</p>' +
                '<p style="font-weight:700;color:' + color + ';">' + perfL + '</p>' +
                '<p class="text-muted" style="margin:8px 0;">' + kpiRow + '</p>' +
                tpBlock + insBlock + '<div>' + qs + '</div>' +
                '<hr class="my-3"><p class="text-muted">' + t('thanks_msg') + '</p></div>';
        }

